var t=[{title:`Die grundlegende Laufposition`,text:`Laufe aufrecht und entspannt, mit einer leichten natürlichen Vorlage des ganzen Körpers und locker schwingenden Armen. Halte die Schultern locker und greife nicht mit jedem Schritt weit nach vorn. Dein Schritt sollte sich bei dem gewählten Tempo koordiniert anfühlen, ohne ihn in eine feste Schablone zu pressen.`},{title:`Schrittfrequenz und Fußaufsatz`,text:`Die Schrittfrequenz ist die Zahl der Schritte pro Minute. Manche Läufer profitieren möglicherweise davon, sie leicht zu ändern, aber keine Regel besagt, dass alle mit 180 Schritten pro Minute laufen müssen. Fersen-, Mittelfuß- und Vorfußaufsatz verteilen Kräfte unterschiedlich, und die Evidenz stützt nicht, jeden gesunden Läufer zu einem Landemuster zu bringen.`},{title:`Geh-Lauf-Intervalle`,text:`Als Anfänger könntest du 15–20 Minuten lang eine Minute leichtes Joggen mit zwei Minuten Gehen abwechseln, plus Aufwärmen und Cool-down. Verlängere über mehrere Wochen die Jogging-Abschnitte. Baue nach Zeit, Selbstvertrauen und dem Anstrengungsgefühl auf und mache Gehpausen, wann immer du sie willst. Die richtige Startmenge hängt davon ab, wie aktiv du warst, wie dein Körper damit umgeht und vom Untergrund, es gibt also keinen festen Plan, dem alle folgen müssen.`},{title:`Sprints sind eine eigene Fertigkeit`,text:`Schnelle Beschleunigungen stellen viel höhere Anforderungen an Muskeln und Sehnen. Baue grundlegende Lauffitness auf, bevor du mit vollem Tempo sprintest, und wärme dich länger auf, wenn du schnellere Belastungen hinzufügst. Höre auf, wenn du stechenden Schmerz oder Schmerz spürst, der schlimmer wird. Wähle Schuhe und eine Strecke, die zu Untergrund und Bedingungen passen, und mache Kondition mit geringer Belastung, wenn Laufen mit deinen Belastungsgrenzen kollidiert oder du keine sichere Strecke hast.`}];var i=[{label:`Systematische Übersichtsarbeit: Fußaufsatztechnik und Verletzungsrisiko`,url:`https://pubmed.ncbi.nlm.nih.gov/34527750/`},{label:`Systematische Übersichtsarbeit zu Schrittfrequenz und Verletzungsrisiko`,url:`https://pubmed.ncbi.nlm.nih.gov/40964543/`},{label:`CDC: Empfehlungen zur körperlichen Aktivität für Erwachsene`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};